import { GoogleGenAI } from "@google/genai";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async getCreativeIdeas(serviceType: string, goal: string) {
    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `I am a client looking for ${serviceType} services. My goal is: ${goal}. As a creative expert at SEF Multimedia Global, suggest 3 unique and creative project ideas or directions we could take to achieve this goal. Keep it concise and professional.`,
        config: {
          systemInstruction: "You are a senior creative consultant at SEF Multimedia Global, a top-tier multimedia agency. Your tone is inspiring, professional, and innovative.",
          temperature: 0.7,
        }
      });
      return response.text;
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "I'm sorry, I'm having trouble coming up with ideas right now. Please contact our team directly for a personalized consultation!";
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState } from 'react';
import { Sparkles, Loader2, Send } from 'lucide-react';
import { geminiService } from '../services/geminiService';

const AIConsultant: React.FC = () => {
  const [service, setService] = useState('Photography');
  const [goal, setGoal] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!goal.trim()) return;

    setLoading(true);
    const suggestion = await geminiService.getCreativeIdeas(service, goal);
    setResult(suggestion || "No results found.");
    setLoading(false);
  };

  return (
    <section className="py-16 bg-gradient-to-br from-slate-900 to-indigo-950 text-white rounded-3xl mx-4 my-12 overflow-hidden relative">
      <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
        <div className="absolute top-[-10%] right-[-10%] w-1/2 h-1/2 bg-blue-500 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-1/2 h-1/2 bg-purple-500 rounded-full blur-[120px]"></div>
      </div>

      <div className="container mx-auto px-6 relative z-10">
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center gap-3 mb-6">
            <Sparkles className="text-yellow-400 w-8 h-8" />
            <h2 className="text-3xl md:text-4xl font-bold league-spartan">AI Creative Consultant</h2>
          </div>

          <p className="text-lg text-slate-300 mb-8">
            Tell us about your brand or project, and our AI-powered creative engine will brainstorm unique directions for you.
          </p>

          <form onSubmit={handleSubmit} className="bg-white/10 backdrop-blur-md p-8 rounded-2xl border border-white/20 shadow-xl">
            <div className="grid md:grid-cols-2 gap-6 mb-6">
              <div>
                <label className="block text-sm font-medium mb-2 text-slate-200">Interest Area</label>
                <select 
                  value={service}
                  onChange={(e) => setService(e.target.value)}
                  className="w-full bg-slate-800/50 border border-slate-700 rounded-lg px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                >
                  <option>Photography</option>
                  <option>Videography</option>
                  <option>Graphic Design</option>
                  <option>Web Development</option>
                  <option>Complete Branding</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-2 text-slate-200">What is your main goal?</label>
                <input 
                  type="text" 
                  value={goal}
                  onChange={(e) => setGoal(e.target.value)}
                  placeholder="e.g. Launching a new eco-friendly jewelry brand"
                  className="w-full bg-slate-800/50 border border-slate-700 rounded-lg px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  required
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 hover:bg-indigo-50 active:bg-indigo-700 hover:text-indigo-900 font-bold py-4 rounded-xl flex items-center justify-center gap-3 transition-all disabled:opacity-50"
            >
              {loading ? (
                <Loader2 className="w-6 h-6 animate-spin" />
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  Brainstorm Ideas
                </>
              )}
            </button>
          </form>

          {result && (
            <div className="mt-8 p-8 bg-white/5 rounded-2xl border border-white/10 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h3 className="text-xl font-semibold mb-4 text-yellow-400 flex items-center gap-2">
                <Sparkles className="w-5 h-5" />
                Suggested Directions:
              </h3>
              <div className="prose prose-invert max-w-none text-slate-200 leading-relaxed whitespace-pre-wrap">
                {result}
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

